head.b:skin:
:root{
--bg:#ffffff;
--text:#1a1a1a;
--accent:#0070f3;
}

body{
margin:0;
font-family:Arial,sans-serif;
background:var(--bg);
color:var(--text);
}

.header{
background:#000;
color:white;
padding:40px 20px;
text-align:center;
border-bottom:4px solid var(--accent);
}

.menu{
background:#111;
padding:12px;
text-align:center;
}

.menu a{
color:white;
text-decoration:none;
font-weight:bold;
margin:0 10px;
}

.container{
max-width:900px;
margin:auto;
padding:20px;
}

.sidebar{
margin-top:30px;
padding:20px;
background:#f5f5f5;
border-radius:10px;
}

.footer{
background:#000;
color:white;
padding:30px;
text-align:center;
margin-top:40px;
}

.post{
padding:20px;
margin-bottom:30px;
border-left:5px solid var(--accent);
background:#fafafa;
}

img{
max-width:100%;
height:auto;
border-radius:8px;
}
